contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 delay, uint256 value, bytes32 salt) public payable {
        require(address(this).balance >= value, "not enough balance");

        address target = address(0xdead);
        bytes memory data = hex"";
        bytes32 predecessor = bytes32(0);

        uint256 minDelay = c.getMinDelay();
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        bool reverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 ts = c.getTimestamp(id);
        bool pending = c.isOperationPending(id);

        if (delay >= minDelay) {
            assert(!reverted && pending && ts > 1 && ts > uint256(1));
        } else {
            assert(reverted && !pending && ts == 0);
        }
    }

    receive() external payable {}
}

