    }

    function run(bytes32 role, bytes32 newAdmin, bytes32 salt, uint256 delay) public {
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        c.grantRole(c.EXECUTOR_ROLE(), address(this));

        bytes32 id = c.hashOperation(address(c), 0, abi.encodeWithSignature("_setupRole(bytes32,address)", bytes32(0), address(0)), bytes32(0), salt);

        c.schedule(address(c), 0, abi.encodeWithSignature("grantRole(bytes32,address)", role, address(this)), bytes32(0), salt, delay);

        c.execute(address(c), 0, abi.encodeWithSignature("grantRole(bytes32,address)", role, address(this)), bytes32(0), salt);

        c.grantRole(c.TIMELOCK_ADMIN_ROLE(), address(this));

        c.schedule(address(c), 0, abi.encodeWithSignature("_setRoleAdmin(bytes32,bytes32)", role, newAdmin), bytes32(0), salt, delay);

        c.execute(address(c), 0, abi.encodeWithSignature("_setRoleAdmin(bytes32,bytes32)", role, newAdmin), bytes32(0), salt);

        assert(c.getRoleAdmin(role) == newAdmin);
    }

    receive() external payable {}
}

